    },
    {
      "indicator": "MM20",
      "reading": "12.9310",
      "interpretation": "MM20 acima do preço; tendência de curto prazo em enfraquecimento."
    },
    {
      "indicator": "MM50",
      "reading": "12.7456",
      "interpretation": "MM50 acima do preço; confirma fraqueza no médio prazo."
    },
    {
